#!/usr/bin/env python3
"""Build .github/scripts/glyphs.json from Inter Tight and JetBrains Mono.

Dev-only tool (needs `pip install fonttools uharfbuzz`). The generated JSON lets
svgkit.py draw text as vector outlines with only the standard library, so the
README art looks identical everywhere without web fonts.

    python extract_glyphs.py InterTight[wght].ttf JetBrainsMono[wght].ttf

Both fonts are licensed under the SIL Open Font License 1.1 (see fonts-OFL.txt).
"""
import io
import json
import os
import sys

import uharfbuzz as hb
from fontTools.pens.basePen import BasePen
from fontTools.ttLib import TTFont
from fontTools.varLib.instancer import instantiateVariableFont

CHARS = [chr(c) for c in range(32, 127)] + list("’‘“”↗→←•·–—…✦")

# style name -> (font index, weight, compute kerning)
STYLES = {
    "display": (0, 800, True),
    "bold": (0, 700, True),
    "semi": (0, 600, True),
    "body": (0, 500, True),
    "mono": (1, 500, False),
    "monob": (1, 800, False),
}


class CmdPen(BasePen):
    """Records outlines as absolute M/L/Q/C/Z commands with integer coordinates."""

    def __init__(self, glyphset):
        super().__init__(glyphset)
        self.out = []

    def _p(self, *pts):
        return " ".join(f"{round(x)} {round(y)}" for x, y in pts)

    def _moveTo(self, p):
        self.out.append("M" + self._p(p))

    def _lineTo(self, p):
        self.out.append("L" + self._p(p))

    def _qCurveToOne(self, p1, p2):
        self.out.append("Q" + self._p(p1, p2))

    def _curveToOne(self, p1, p2, p3):
        self.out.append("C" + self._p(p1, p2, p3))

    def _closePath(self):
        self.out.append("Z")


def build_style(path, weight, kern):
    font = instantiateVariableFont(TTFont(path), {"wght": weight}, inplace=False)
    buf = io.BytesIO()
    font.save(buf)
    blob = buf.getvalue()
    cmap = font.getBestCmap()
    gs = font.getGlyphSet()
    hmtx = font["hmtx"]
    glyphs = {}
    for ch in CHARS:
        name = cmap.get(ord(ch))
        if not name:
            continue
        pen = CmdPen(gs)
        gs[name].draw(pen)
        glyphs[ch] = [hmtx[name][0], "".join(pen.out)]
    pairs = {}
    if kern:
        hbfont = hb.Font(hb.Face(blob))
        feats = {"kern": True, "liga": False, "calt": False}
        keys = [c for c in glyphs if c != " "]
        for a in keys:
            for b in keys:
                buf = hb.Buffer()
                buf.add_str(a + b)
                buf.guess_segment_properties()
                hb.shape(hbfont, buf, feats)
                if len(buf.glyph_positions) != 2:
                    continue
                diff = buf.glyph_positions[0].x_advance - glyphs[a][0]
                if diff:
                    pairs[a + b] = diff
    os2 = font["OS/2"]
    return {
        "upm": font["head"].unitsPerEm,
        "cap": getattr(os2, "sCapHeight", 0),
        "xh": getattr(os2, "sxHeight", 0),
        "glyphs": glyphs,
        "kern": pairs,
    }


def main():
    paths = sys.argv[1:3]
    out = {"_note": "Generated by extract_glyphs.py from Inter Tight + JetBrains Mono (SIL OFL 1.1).", "styles": {}}
    for style, (idx, weight, kern) in STYLES.items():
        out["styles"][style] = build_style(paths[idx], weight, kern)
        print(style, len(out["styles"][style]["glyphs"]), "glyphs", len(out["styles"][style]["kern"]), "kern pairs")
    dest = os.path.join(os.path.dirname(os.path.abspath(__file__)), "glyphs.json")
    with open(dest, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, separators=(",", ":"))
    print("wrote", dest, os.path.getsize(dest), "bytes")


if __name__ == "__main__":
    main()
